CREATE TABLE IF NOT EXISTS candidates(id TEXT PRIMARY KEY,name TEXT NOT NULL,role TEXT NOT NULL,experience NUMERIC NOT NULL,skills TEXT NOT NULL,notice INTEGER NOT NULL,summary TEXT NOT NULL,resume_text TEXT NOT NULL DEFAULT '',consent BOOLEAN NOT NULL DEFAULT TRUE,stage TEXT NOT NULL DEFAULT 'Sourced',content_hash TEXT UNIQUE);
CREATE TABLE IF NOT EXISTS jobs(id SERIAL PRIMARY KEY,title TEXT NOT NULL,client TEXT NOT NULL,location TEXT NOT NULL,min_exp NUMERIC NOT NULL,max_exp NUMERIC NOT NULL,skills TEXT NOT NULL,max_notice INTEGER NOT NULL,ctc_range TEXT NOT NULL DEFAULT '',status TEXT NOT NULL DEFAULT 'Open');
CREATE TABLE IF NOT EXISTS submissions(job_id INTEGER REFERENCES jobs(id),candidate_id TEXT REFERENCES candidates(id) ON DELETE CASCADE,status TEXT NOT NULL DEFAULT 'Pending',reason TEXT NOT NULL DEFAULT '',interview_slot TEXT NOT NULL DEFAULT '',PRIMARY KEY(job_id,candidate_id));
CREATE TABLE IF NOT EXISTS audit(id BIGSERIAL PRIMARY KEY,actor TEXT NOT NULL,action TEXT NOT NULL,candidate_id TEXT NOT NULL,created_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
